import java.nio.file.*;

public class PathDemo {
    public static void main(String[] args) {
        Path filePath = Paths.get("C:\\Java\\Chapter8\\sample.txt");

        System.out.println("Path:       " + filePath.toString());
        System.out.println("File name:  " + filePath.getFileName());
        System.out.println("Elements:   " + filePath.getNameCount());

        for (int i = 0; i < filePath.getNameCount(); i++) {
            System.out.println("  Name " + i + ": " + filePath.getName(i));
        }
    }
}

