import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;

public class AttributesDemo {
    public static void main(String[] args) {
        Path filePath = Paths.get("sample.txt");

        try {
            BasicFileAttributes attr =
                Files.readAttributes(filePath, BasicFileAttributes.class);

            System.out.println("Size:     " + attr.size() + " bytes");
            System.out.println("Created:  " + attr.creationTime());
            System.out.println("Modified: " + attr.lastModifiedTime());
        } catch (IOException e) {
            System.out.println("Could not read attributes: " + e.getMessage());
        }
    }
}
